const raw = $('DB | Load Airtable Sync Context').item.json.sync_context;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;
if (!ctx || ctx.connector_key !== 'airtable_leads') throw new Error('AIRTABLE_SYNC_CONTEXT_INVALID');
let gate = ctx.reliability_gate;
if (typeof gate === 'string') gate = JSON.parse(gate);
const allowed = gate?.allowed === true;
return {sync_context:ctx,should_sync:allowed,skip_reason:allowed?null:'RELIABILITY_CIRCUIT_OPEN'};

const raw = $('DB | Load Airtable Sync Context').first().json.sync_context;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;
const rows = $input.all().map(item => item.json ?? {});
if (rows.length > 10000) throw new Error('AIRTABLE_SYNC_RESULT_LIMIT_EXCEEDED');

const parseDate = value => {
  if (value === null || value === undefined || value === '') return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};
const records=[];
let rejectedCount=0;
let earliestRejectedAt=null;

for (const r of rows) {
  const id=String(r.id ?? r.recordId ?? '').trim();
  const createdAt=parseDate(r.createdTime ?? r['Created time'] ?? r['Created At']);
  const updatedAt=parseDate(r['Last Modified'] ?? r['Last modified'] ?? r['Last Modified Time'] ?? createdAt);
  const valid=id.length>0 && id.length<=200 && createdAt!==null;
  if (!valid) {
    rejectedCount += 1;
    const candidate=updatedAt ? new Date(updatedAt).getTime() : null;
    if (candidate!==null && (earliestRejectedAt===null || candidate<earliestRejectedAt)) earliestRejectedAt=candidate;
    continue;
  }

  // Lifecycle timestamps are only populated when explicit source fields exist.
  // AI Qualified / AI Score alone are not treated as timestamp evidence.
  records.push({
    source_record_id:id,
    source_payload:{
      'Assigned Owner':r['Assigned Owner'] ?? null,
      'Team size':r['Team size'] ?? null,
      'Business type':r['Business type'] ?? null,
      revint_lead_source:r['Lead Source'] ?? 'airtable_intake',
      revint_created_at:createdAt,
      revint_mql_at:parseDate(r['MQL at']),
      revint_sql_at:parseDate(r['SQL at']),
      revint_opportunity_at:parseDate(r['Opportunity at']),
      revint_won_at:parseDate(r['Won at']),
      revint_lost_at:parseDate(r['Lost at']),
      revint_source_updated_at:updatedAt
    }
  });
}

const queryStart=new Date(ctx.query_start_at).getTime();
const queryEnd=new Date(ctx.query_end_at).getTime();
let watermarkMs=queryEnd;
if (rejectedCount>0) watermarkMs=earliestRejectedAt===null ? queryStart : Math.max(queryStart,earliestRejectedAt);

return [{json:{
  connector_key:'airtable_leads',
  query_start_at:new Date(queryStart).toISOString(),
  query_end_at:new Date(queryEnd).toISOString(),
  watermark:new Date(watermarkMs).toISOString(),
  source_count:rows.length,
  record_count:records.length,
  rejected_count:rejectedCount,
  records,
  event_id:'AIRTABLE-SYNC-' + String(queryEnd)
}}];
